export default function Page() {
  const products = [
    { name: 'Orbit', color: 'from-indigo-400 to-purple-500' },
    { name: 'Relay', color: 'from-emerald-400 to-teal-500' },
    { name: 'Beacon', color: 'from-orange-400 to-pink-500' }
  ];
  return (
    <div className="min-h-screen bg-gray-50 py-12 px-4">
